function send(type,data={}){if(socket?.readyState!==WebSocket.OPEN){notify('ارتباط با سرور قطع است.');return}if(!authorized&&type!=='auth'){notify('برای مدیریت، ابتدا وارد پنل شوید.');return}socket.send(JSON.stringify({type,...data}))}
function notify(text){$('notice').textContent=text}
function node(tag,cls,text){const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el}
function avatar(person,ring=true){const box=node('span','avatar');box.append(node('span','initial',(person?.name||'?').slice(0,1)));if(person?.avatar&&/^(https:\/\/|data:image\/(png|jpeg|webp);base64,|\/avatars\/preview-[1-8]\.svg$)/.test(person.avatar)){const img=node('img');img.src=person.avatar;img.alt=person.name;img.referrerPolicy='no-referrer';img.onerror=()=>img.remove();box.append(img)}if(ring){const canvas=node('canvas','ring');canvas.width=180;canvas.height=180;box.append(canvas)}return box}
function flagEmoji(flag){return Array.from(flag||'').map(c=>String.fromCharCode(c.codePointAt(0)-0x1f1e6+97)).join('')}
function flag(flag){const img=node('img','flag');img.src='/flags/'+flagEmoji(flag)+'.svg';img.alt=flag;img.onerror=()=>img.replaceWith(node('span','flag',flag));return img}
function connect(){clearTimeout(reconnectTimer);lastSocketMessageAt=Date.now();socket=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+'/events');socket.onopen=()=>{if(screen)socket.send(JSON.stringify({type:'race-screen-ready'}));if(token)send('auth',{token})};socket.onmessage=e=>{lastSocketMessageAt=Date.now();let m;try{m=JSON.parse(e.data)}catch{return}if(m.type==='snapshot'){lastMessage=m;serverOffset=(m.serverNow||Date.now())-Date.now();race=m.snapshot.race;window.__raceServerOffset=serverOffset;if(race)render();return}if(m.type==='auth'){authorized=!!m.ok;$('operatorBar').hidden=!screen||!authorized;$('auth').hidden=authorized;$('tools').hidden=!authorized;notify(authorized?'پنل باز شد.':'کلید مدیریت معتبر نیست.');return}if(m.type==='race-audio-status'){showAudioStatus(m);return}if(m.type==='race-audio-test'||m.type==='race-audio-local-test'){if(m.kind==='engine'||m.kind==='music'){unlockEngineAudio();if(window.RaceSound)RaceSound.test(m.kind);else engineTestUntil=Date.now()+5000;updateEngineAudio()}else{window.RaceHost?.quiet(15000);RaceVoice.configure(race.settings);RaceVoice.playClip('test',{force:true})}return}if(m.type==='race-screen-refresh'){if(screen)location.reload();return}if(m.type==='race-join')welcome(m);if(m.type==='error'||m.type==='notice')notify(m.message);if(m.type==='race-reaction')burst(m.kind)};socket.onclose=()=>{authorized=false;$('tools').hidden=true;$('auth').hidden=false;$('liveBadge').textContent='● RECONNECTING';$('connectionStatus').textContent='ارتباط با سرور قطع شد؛ تلاش دوباره…';reconnectTimer=setTimeout(connect,2000)};socket.onerror=()=>socket.close()}
