let winnerKey='';function renderWinner(){const r=race,box=$('winner'),key=r.round+':'+r.winner;box.hidden=r.winner===null;if(key===winnerKey)return;winnerKey=key;box.replaceChildren();if(r.winner!==null){const p=r.winnerResult||r.slots[r.winner],result=r.winnerResult,activity=r.roundAudit?.[p?.id];const noWinner=result?.noWinner??(!!p?.isDemo||!((activity?.likeCount||0)>0||(activity?.likePoints||0)>0||(activity?.gifts||0)>0));box.classList.toggle('no-winners',noWinner);if(noWinner){box.append(node('h2','','No winners'));return}if(r.settings.celebrationMusic)victoryTune();box.append(node('span','trophy','🏆'),avatar(p),node('h2','',p?.name||'WINNER'),node('p','',p?.isDemo?'DEMO WINNER':'WINNER'));if(result){const fmt=n=>Number(n).toLocaleString('en-US',{maximumFractionDigits:2});box.append(node('strong','winner-coins',fmt(result.winnerCoins)+' '+(result.mode==='fixed'?'GAME COINS':'COINS')),node('p','winner-score','SCORE '+fmt(result.assistScore??result.score)));}const follow=followLink(p);if(follow)box.append(follow);burst('gift')}}
function renderSettings(){const form=$('settings');if(form.dataset.dirty!=='true'&&!form.contains(document.activeElement)&&document.activeElement?.form!==form)for(const [k,v]of Object.entries(race.settings)){const input=form.elements.namedItem(k);if(input){if(input.type==='checkbox')input.checked=v;else input.value=v}}const key=JSON.stringify([race.settings.cars,race.flags,race.giftMap,race.giftNames]);if($('slotSettings').dataset.key!==key&&!$('slotSettings').contains(document.activeElement)){$('slotSettings').dataset.key=key;$('slotSettings').replaceChildren();for(let i=0;i<race.settings.cars;i++){const row=node('form','slot-row'),label=node('label','','موتر '+(i+1)),input=node('input');input.value=race.flags[i];input.setAttribute('aria-label','بیرق موتر '+(i+1));input.maxLength=8;const select=node('select');select.setAttribute('aria-label','گیفت موتر '+(i+1));for(const [id,title]of allGifts()){const o=node('option','',title);o.value=id;select.append(o)}select.value=race.giftMap[i];const manual=node('input');manual.placeholder='شناسهٔ دستی گیفت';manual.inputMode='numeric';manual.setAttribute('aria-label','شناسهٔ دستی گیفت موتر '+(i+1));const giftName=node('input');giftName.placeholder='نام گیفت دستی';giftName.maxLength=70;const button=node('button','','ذخیرهٔ بیرق و گیفت');row.append(label,input,select,manual,giftName,button);row.onsubmit=e=>{e.preventDefault();send('race-slot',{index:i,flag:input.value.trim(),giftId:manual.value.trim()||select.value,giftName:giftName.value.trim()})};$('slotSettings').append(row)}}const test=$('testGift');if(!test.matches(':focus')){const old=test.value;test.replaceChildren();for(const [id,title]of allGifts()){const o=node('option','',title);o.value=id;test.append(o)}if([...test.options].some(o=>o.value===old))test.value=old}}
function renderManagement(){const list=$('managePlayers'),key=JSON.stringify([...race.slots,...race.queue].map(p=>[p?.id,p?.name,p?.avatar]));if(list.dataset.key!==key&&!list.contains(document.activeElement)){list.dataset.key=key;list.replaceChildren();[...race.slots.map((p,i)=>p&&!p.isDemo?{...p,label:'موتر '+(i+1)}:null),...race.queue.map(p=>({...p,label:'انتظار'}))].filter(Boolean).forEach(p=>{const row=node('div','manage-row'),name=node('input'),photo=node('input'),save=node('button','','ذخیره نام و عکس'),remove=node('button','','خروج'),block=node('button','danger','مسدود');name.value=p.name;name.maxLength=40;name.setAttribute('aria-label','نام '+p.name);photo.type='file';photo.accept='image/png,image/jpeg,image/webp';photo.setAttribute('aria-label','عکس '+p.name);let image=p.avatar;photo.onchange=async()=>{const f=photo.files[0];if(!f)return;if(!/^image\/(png|jpeg|webp)$/.test(f.type)||f.size>5000000){notify('عکس PNG، JPEG یا WebP تا ۵ مگابایت انتخاب کنید.');return}const bitmap=await createImageBitmap(f);const c=document.createElement('canvas');c.width=c.height=100;const size=Math.min(bitmap.width,bitmap.height);c.getContext('2d').drawImage(bitmap,(bitmap.width-size)/2,(bitmap.height-size)/2,size,size,0,0,100,100);image=c.toDataURL('image/jpeg',.8);bitmap.close()};save.onclick=()=>send('race-edit',{userId:p.id,name:name.value.trim(),avatar:image});remove.onclick=()=>send('race-remove',{userId:p.id});block.onclick=()=>send('remove-user',{userId:p.id});row.append(node('span','',p.label),name,photo,save,remove,block);list.append(row)})}const restore=$('restorePlayers');restore.replaceChildren();const people=new Map((race.removed||[]).map(p=>[p.id,p.name]));for(const id of lastMessage.snapshot.blockedUsers||[])if(!people.has(id))people.set(id,id);for(const [id,name]of people){const row=node('div','manage-row'),button=node('button','','رفع مسدودی / برگشت به صف');button.onclick=()=>send('race-restore',{userId:id});row.append(node('span','',name),button);restore.append(row)}}
function allGifts(){const map=new Map(gifts);for(const [id,name]of Object.entries(race?.giftNames||{}))map.set(id,name);return [...map]}
function giftTitle(id){return race?.giftNames?.[id]||gifts.find(g=>g[0]===id)?.[1]||'Gift #'+id}
function frameLevel(p,field){const s=race.settings,chosen=field==='likes'?s.likerFrame:s.gifterFrame;if(chosen&&chosen!=='auto')return chosen;if(field==='likes')return p.likes>=1000?'gold':p.likes>100?'glow':'simple';const latest=p.lastGiftCoins??p.lastGiftCount;const value=(p.highlightUntil||0)>Date.now()+serverOffset?Math.max(latest||0,p.highlightValue||0):latest;if(value==null)return 'glow';return value>=s.tierFire?'fire':value>=s.tierIce?'ice':value>=s.tierGold?'gold':value>=s.tierSilver?'silver':value>=s.tierSimple?'simple':'glow'}
function renderDiagnostics(){const c=lastMessage.connection||{};$('diagnostics').textContent='Connection: '+(c.status||'disconnected')+'\nAccount: '+(lastMessage.username||'—')+'\nRetry: '+(c.retryAttempt||0)+(c.retryAt?' · '+Math.max(0,Math.ceil((c.retryAt-Date.now())/1000))+'s':'')+'\n'+(c.diagnostics||[]).map(d=>[d.reason,d.httpStatus,d.route].filter(Boolean).join(' · ')).join('\n');$('giftEvents').textContent=(race.events||[]).map(e=>new Date(e.at).toLocaleTimeString()+' · '+(e.name||'Viewer')+' · '+(e.kind==='gift'?'Gift #'+e.giftId+' × '+e.count+' · '+e.reason:'JOIN')).join('\n')||'هنوز رویدادی ثبت نشده است.'}
function welcome(m){const toast=node('div','join-toast');const copy=node('span','join-copy');copy.append(node('strong','',m.name||'Viewer'));toast.append(avatar({name:m.name,avatar:m.avatar},false),copy);$('joinToasts').append(toast);setTimeout(()=>toast.remove(),6500);while($('joinToasts').children.length>4)$('joinToasts').firstElementChild.remove();if(screen)window.RaceHost?.arrival(m);if(!window.RaceHost?.enabled&&screen&&m.welcomeVoiceEligible&&race?.settings.welcomeVoice&&race.settings.sound){RaceVoice.configure(race.settings);RaceVoice.speakName(m.name||'Viewer')}}
let audio;document.addEventListener('pointerdown',()=>unlockEngineAudio());
function burst(kind){if(race?.settings.sound&&audio?.state==='running'){const tone=audio.createOscillator(),gain=audio.createGain();tone.connect(gain);gain.connect(audio.destination);tone.frequency.value=kind==='like'?660:880;gain.gain.setValueAtTime(Math.max(.001,race.settings.volume/100*.12),audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.18);tone.start();tone.stop(audio.currentTime+.2)}if(race?.settings.effects===false)return;if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const el=node('span','reaction',kind==='like'?'♥':'🎁');$(kind==='like'?'likerRail':'gifterRail').append(el);setTimeout(()=>el.remove(),1400)}
function animate(time){animationFrame=requestAnimationFrame(animate);if(time-lastTick<33)return;const dt=Math.min(100,time-lastTick||33);lastTick=time;document.querySelectorAll('.vehicle').forEach(v=>{const target=v._target||0,current=matchMedia('(prefers-reduced-motion: reduce)').matches?target:v._position||0;v._position=Math.abs(target-current)<.02?target:current+(target-current)*Math.min(1,dt/220);const fraction=Math.max(0,Math.min(1,v._position/(v._length||1000)));const roadHeight=v.parentElement.clientHeight,start=roadHeight*.04,end=Math.max(start,roadHeight*.93-v.offsetHeight);v.style.bottom=(start+fraction*(end-start))+'px';v.classList.toggle('moving',Math.abs(target-current)>.05)});if(race){const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;for(const canvas of document.querySelectorAll('canvas.ring')){if(!canvas.getClientRects().length)continue;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,180,180);const level=canvas.dataset.level||race.settings.ring;if(level==='none')continue;drawCloudProfileRing(ctx,90,90,108,level,reduced||race.settings.effects===false?0:time,{speed:race.settings.ringSpeed/100,intensity:race.settings.ringIntensity/100,ornaments:race.settings.ornaments})}}}
$('panelToggle').onclick=()=>{$('panel').hidden=!$('panel').hidden};$('closePanel').onclick=()=>{$('panel').hidden=true};$('unlock').onclick=()=>{token=$('adminKey').value.trim();sessionStorage.setItem('race-admin',token);send('auth',{token});$('adminKey').value=''};$('connect').onclick=()=>send('connect',{username:$('username').value.trim()});$('disconnect').onclick=()=>send('disconnect');$('startDemo').onclick=()=>send('demo-start');$('stopDemo').onclick=()=>send('demo-stop');$('newRound').onclick=()=>send('race-new');$('settings').onsubmit=e=>{e.preventDefault();const settings={};for(const el of e.target.elements)if(el.name)settings[el.name]=el.type==='checkbox'?el.checked:el.tagName==='SELECT'||el.type==='color'||el.type==='hidden'?el.value:Number(el.value);e.target.dataset.dirty='';send('race-settings',{settings})};document.querySelectorAll('[data-test]').forEach(b=>b.onclick=()=>send('race-demo',{action:b.dataset.test,userId:$('testId').value,name:$('testName').value,count:Number($('testCount').value),giftId:$('testGift').value,content:$('testCountry').value.trim()}));
function tone(hz,delay=0){if(!audio)unlockEngineAudio();if(audio?.state!=='running'){if(audio?.state==='suspended')audio.resume().catch(()=>{});$('audioUnlock').hidden=false;return;}const osc=audio.createOscillator(),gain=audio.createGain(),at=audio.currentTime+delay;osc.connect(gain);gain.connect(audio.destination);osc.frequency.value=hz;gain.gain.setValueAtTime(Math.max(.001,(race?.settings.volume||20)/100*.1),at);gain.gain.exponentialRampToValueAtTime(.001,at+.2);osc.start(at);osc.stop(at+.22)}
