for(const id of ['likerFrame','gifterFrame'])for(const [value,label]of Object.entries({auto:'خودکار بر اساس امتیاز',none:'بدون قاب',cloud:'ابری ساده',simple:'ابری ملایم',glow:'ابری نورانی',silver:'ابری نقره‌ای',gold:'ابری طلایی',ice:'ابری یخی',fire:'ابری گرم'})){const option=node('option','',label);option.value=value;$(id).append(option)}
$('screenURL').value=location.origin+'/screen';$('copyScreen').onclick=async()=>{try{await navigator.clipboard.writeText($('screenURL').value);notify('لینک نمایش کپی شد.')}catch{$('screenURL').select();notify('لینک را کپی کنید.')}};const soundTest=()=>{unlockEngineAudio();RaceVoice.unlock();if(authorized){const fields=$('settings').elements;send('race-settings',{settings:{sound:true,voiceStyle:fields.namedItem('voiceStyle')?.value||race.settings.voiceStyle,volume:Math.max(20,Number(fields.namedItem('volume')?.value)||race.settings.volume)}});send('race-audio-test')}else{RaceVoice.configure({...race.settings,sound:true});RaceVoice.playClip('test',{force:true})}};$('testSound').onclick=soundTest;$('screenSound').onclick=soundTest;$('screenTestSound').onclick=soundTest;const pause=()=>send('race-settings',{settings:{paused:!race.settings.paused}});$('pauseRace').onclick=pause;$('screenPause').onclick=pause;$('screenNext').onclick=()=>send('race-new');$('clearTests').onclick=()=>send('race-clear-tests');$('addPlayer').onclick=()=>send('race-add',{userId:$('manualId').value.trim(),name:$('manualName').value.trim()});
