function modeLabel(){return race.settings.playMode==='gifts'?'فقط گیفت':race.settings.giftsEnabled?'لایک + گیفت کمکی':'فقط لایک'}
function renderModes(){const giftMode=race.settings.playMode==='gifts';const mixed=race.settings.playMode==='mixed';$('playMode').value=race.settings.playMode;const manual=race.settings.entryMode==='manual';$('manualMovement').hidden=!manual;$('manualInputMethod').value=race.settings.playMode;$('modeMixed').setAttribute('aria-pressed',String(!manual&&mixed));$('modeManual').setAttribute('aria-pressed',String(manual));$('modeLikes').setAttribute('aria-pressed',String(!manual&&!giftMode&&!mixed));$('modeGifts').setAttribute('aria-pressed',String(!manual&&giftMode));const prompt=$('manualJoinPrompt');prompt.hidden=!manual||race.settings.running;prompt.textContent='COMMENT 1–'+race.settings.cars+' TO JOIN · WAIT FOR START';$('giftAssist').checked=race.settings.giftsEnabled;$('giftAssist').disabled=giftMode||mixed;$('giftAssistLabel').textContent=giftMode?'حرکت با گیفت در این حالت فعال است':'گیفت کمکی در بازی با لایک';$('modeDescription').textContent=manual?'ثبت دستی: بیننده شمارهٔ موتر را ۱ تا '+race.settings.cars+' کامنت می‌کند. پس از ثبت افراد، دکمهٔ «شروع مسابقه» را بزنید؛ کامنت به‌تنهایی بازی را شروع نمی‌کند.':giftMode?'حالت گیفت: فقط گیفت مشخص موتر، آن را حرکت می‌دهد؛ لایک حرکت ایجاد نمی‌کند.':race.settings.giftsEnabled?'حالت لایک + گیفت: هر ۱۰ لایک برای موتر خودتان یک قدم؛ گیفت‌ها مطابق بازهٔ زمانی تنظیم‌شده به امتیاز تبدیل می‌شوند.':'حالت لایک: هر ۱۰ لایک برای موتر خودتان یک قدم. برای حرکت با گیفت هم، گزینهٔ گیفت کمکی را روشن کنید.'}
$('modeLikes').onclick=()=>send('race-settings',{settings:{playMode:'likes',entryMode:'auto',demoOpponents:true,giftsEnabled:false}});$('modeGifts').onclick=()=>send('race-settings',{settings:{playMode:'gifts',entryMode:'auto',demoOpponents:true}});$('giftAssist').onchange=()=>send('race-settings',{settings:{giftsEnabled:$('giftAssist').checked}});

function renderDriverRoster(){const root=$('driverRoster');while(root.children.length>race.settings.cars)root.lastElementChild.remove();for(let i=0;i<race.settings.cars;i++){const p=race.slots[i];let card=root.children[i];if(!card){card=node('button','roster-card');card.type='button';card.onclick=()=>showSupporters(i);card.style.setProperty('--car',(race.carStyles?.[i]?.color||palette[i]));root.append(card)}const signature=JSON.stringify([p?.id,p?.name,p?.avatar,p?.isDemo,p?.countryFlag,race.flags[i],race.giftMap[i],race.giftNames]);if(card.dataset.profile!==signature){card.dataset.profile=signature;card.replaceChildren(avatar(p),node('span','roster-number',String(i+1)));const copy=node('span','roster-copy');copy.append(node('strong','roster-name',p?.name||'OPEN SLOT'),node('small','roster-gift',giftTitle(race.giftMap[i])));const chosenFlag=racerFlag(p,i);if(chosenFlag)copy.querySelector('.roster-name').prepend(flag(chosenFlag));card.append(copy,node('span','roster-distance'));card.classList.toggle('is-demo',!!p?.isDemo);if(p?.isDemo)copy.append(node('small','demo-label','DEMO'))}card.querySelector('.roster-distance').textContent=Math.floor(p?.distance||0)+'m';card.setAttribute('aria-label','موتر '+(i+1)+' · '+(p?.name||'OPEN SLOT'))}}

function racerFlag(person,index){return person?.isDemo?race.flags[index]:person?.countryFlag||''}

let lastRaceLeader=null,lastLeaderRound=0;
function renderCompetition(){const rows=race.slots.slice(0,race.settings.cars).map((p,i)=>({p,i})).filter(x=>x.p).sort((a,b)=>b.p.distance-a.p.distance||a.i-b.i),top=rows[0];if(lastLeaderRound!==race.round){lastRaceLeader=null;lastLeaderRound=race.round}for(let position=0;position<rows.length;position++){const {p,i}=rows[position],card=$('driverRoster').children[i],lane=$('track').querySelectorAll(':scope > .lane')[i];if(!card||!lane)continue;let badge=card.querySelector('.roster-position');if(!badge){badge=node('span','roster-position');card.append(badge)}badge.textContent='P'+(position+1);const isLead=position===0&&p.distance>0;card.classList.toggle('race-leader',isLead);lane.classList.toggle('race-leader',isLead);card.style.setProperty('--progress',Math.min(100,p.distance/race.settings.length*100)+'%')}if(top?.p.distance>0){if(lastRaceLeader!==null&&lastRaceLeader!==top.p.id&&race.settings.effects&&!matchMedia('(prefers-reduced-motion: reduce)').matches){$('track').classList.remove('overtake');void $('track').offsetWidth;$('track').classList.add('overtake');setTimeout(()=>$('track').classList.remove('overtake'),900)}lastRaceLeader=top.p.id}document.body.classList.toggle('final-sprint',!!top&&top.p.distance/race.settings.length>=.8)}

for(const [id,action]of [['raceStart','start'],['racePause','pause'],['raceResume','resume'],['raceStop','stop']])$(id).onclick=()=>send('race-control',{action});
function renderRaceControls(){const s=race.settings;if(window.updatePanelMotion)window.updatePanelMotion(s);const state=!s.running?'متوقف کامل':s.paused?'توقف موقت':Date.now()+serverOffset<race.startsAt?'شمارش معکوس':'در حال مسابقه';$('raceControlStatus').textContent='وضعیت: '+state;$('racePause').disabled=!s.running||s.paused;$('raceResume').disabled=!s.running||!s.paused;$('raceStop').disabled=!s.running;}

let selectedAuditRound='current';
function currentAudit(){const rows=Object.values(race.roundAudit||{}).map(x=>({...x}));for(const p of race.slots){if(!p||p.isDemo)continue;let x=rows.find(x=>x.id===p.id);if(!x){x={id:p.id,name:p.name,gifts:0,coins:0,giftPoints:0,groupedGifts:0,pointsForOtherCars:0};rows.push(x)}x.score=p.autoPilot?(p.assistPoints||0):p.distance/race.settings.step;x.pendingMoves=(p.giftMoveQueue||0)+(p.pendingSteps||0);x.reason='RACE IN PROGRESS'}return {round:race.round,rows}}
function chosenAudit(){return selectedAuditRound==='current'?(race.winner!==null?race.roundReports?.find(x=>x.round===race.round):currentAudit()):(race.roundReports||[]).find(x=>String(x.round)===selectedAuditRound)}
function auditTable(report,compact=false){const table=node('table','audit-table');const head=node('tr');for(const title of compact?['PLAYER','POINTS','GIFTS','COINS*','RESULT']:['PLAYER','RACE POINTS','GIFTS','COINS*','GIFT POINTS','GROUPED','OTHER CARS','PENDING','REASON'])head.append(node('th','',title));const thead=node('thead');thead.append(head);table.append(thead);const body=node('tbody');for(const row of report?.rows||[]){const tr=node('tr',row.winner?'audit-winner':'');const values=compact?[row.name,Number(row.score||0).toFixed(1),row.gifts||0,row.coins||0,row.winner?'WINNER':row.reason||'IN PROGRESS']:[row.name,Number(row.score||0).toFixed(1),row.gifts||0,row.coins||0,row.giftPoints||0,row.groupedGifts||0,row.pointsForOtherCars||0,row.pendingMoves||0,row.reason||'IN PROGRESS'];for(const value of values)tr.append(node('td','',String(value)));body.append(tr)}table.append(body);return table}
function renderAudit(){const select=$('auditRound');const options=[['current','دور جاری'],...(race.roundReports||[]).map(r=>[String(r.round),'دور '+r.round])];const key=JSON.stringify(options);if(select.dataset.key!==key){select.dataset.key=key;select.replaceChildren();for(const [value,label]of options){const o=node('option','',label);o.value=value;select.append(o)}select.value=selectedAuditRound}const report=chosenAudit();const panel=$('auditPanel');const signature=JSON.stringify(report);if(panel.dataset.key!==signature){panel.dataset.key=signature;panel.replaceChildren(auditTable(report))}const live=$('liveAudit');live.hidden=!(race.settings.showResultTable&&race.winner!==null);const final=(race.roundReports||[]).find(r=>r.round===race.round);const liveKey=JSON.stringify(final);if(live.dataset.key!==liveKey){live.dataset.key=liveKey;live.replaceChildren(node('h2','','ROUND '+race.round+' · RACE POINTS'),auditTable(final,true))}}
$('auditRound').onchange=e=>{selectedAuditRound=e.target.value;renderAudit()};$('showAudit').onclick=()=>send('race-settings',{settings:{showResultTable:!race.settings.showResultTable}});$('downloadAudit').onclick=()=>{const report=chosenAudit();if(!report)return;const cells=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,m=>"'"+m).replace(/"/g,'""')+'"';const rows=[['ROUND','PLAYER','POINTS','GIFTS','COINS','GIFT POINTS','GROUPED','OTHER CARS','PENDING','REASON'],...report.rows.map(x=>[report.round,x.name,x.score,x.gifts,x.coins,x.giftPoints,x.groupedGifts,x.pointsForOtherCars,x.pendingMoves,x.reason])];const csv='\uFEFF'+rows.map(row=>row.map(cells).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=node('a');a.href=url;a.download='race-round-'+report.round+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};

let raceFitPending=false;function scheduleRaceFit(){if(!screen||raceFitPending)return;raceFitPending=true;requestAnimationFrame(()=>{raceFitPending=false;const road=document.querySelector('.road');if(!road)return;const lane=document.querySelector('.lane');const carScale=Math.min(innerWidth<700?1:1.45,(lane?.clientWidth||80)*.70/64);$('stage').style.setProperty('--race-car-scale',String(carScale));const headers=[...document.querySelectorAll('.lane>.driver')];headers.forEach(e=>e.style.height='auto');const maxHeader=Math.max(0,...headers.map(e=>e.getBoundingClientRect().height));headers.forEach(e=>e.style.height=maxHeader+'px');const fullView=window.visualViewport?.height||innerHeight;const safe=race?.settings.liveBottomInsetPercent??28;const view=fullView*(1-safe/100);document.documentElement.style.setProperty('--live-safe-bottom',safe+'svh');const stage=$('stage'),minimumRoad=Math.min(fullView<650?(race?.queue.length?60:80):120,view*.2);stage.style.setProperty('--minimum-road',minimumRoad+'px');const overhead=stage.getBoundingClientRect().height-road.getBoundingClientRect().height;const height=Math.max(minimumRoad,Math.min(view*.65,view-overhead-8));const value=Math.round(height)+'px';if(stage.style.getPropertyValue('--race-road-height')!==value)stage.style.setProperty('--race-road-height',value);const center=document.querySelector('.race-center'),rect=road.getBoundingClientRect();const rail=$('supportSpotlight');if(rail)center.style.setProperty('--support-space',Math.max(70,rect.bottom-rail.getBoundingClientRect().top-6)+'px');center.style.setProperty('--move-dock-top',Math.round(rect.top-center.getBoundingClientRect().top+5)+'px');center.style.setProperty('--move-prompt-top',Math.round(rect.top-center.getBoundingClientRect().top+rect.height/2)+'px')})}window.addEventListener('resize',scheduleRaceFit);window.visualViewport?.addEventListener('resize',scheduleRaceFit);document.fonts.ready.then(scheduleRaceFit);

function renderCarAppearance(){const root=$('carAppearance'),key=JSON.stringify([race.settings.cars,race.carStyles]);if(root.dataset.key===key||root.contains(document.activeElement))return;root.dataset.key=key;root.replaceChildren();for(let i=0;i<race.settings.cars;i++){const style=race.carStyles?.[i]||{color:palette[i],model:'gt'};const form=node('form','car-style-row'),label=node('strong','','موتر '+(i+1)),color=node('input'),model=node('select'),save=node('button','','ذخیرهٔ مدل و رنگ');color.type='color';color.value=style.color;color.setAttribute('aria-label','رنگ موتر '+(i+1));model.setAttribute('aria-label','مدل موتر '+(i+1));for(const [value,title]of [['formula','Formula · فرمول'],['gt','GT · سوپراسپورت'],['rally','Rally · رالی']]){const o=node('option','',title);o.value=value;model.append(o)}model.value=style.model;form.append(label,color,model,save);form.onsubmit=e=>{e.preventDefault();send('race-style',{index:i,color:color.value,model:model.value})};root.append(form)}}

$('modeManual').onclick=()=>send('race-settings',{settings:{entryMode:'manual',autoRestart:false}});

function renderSpotlight(){if(!race)return;const root=$('supportSpotlight'),now=Date.now()+serverOffset,recent=race.lastGiftSupporter,activeGift=(race.gifters||[]).some(p=>(p.highlightUntil||((p.lastGiftAt||p.at||0)+60000))>now);const sort=(people,field,count)=>[...(people||[])].sort((a,b)=>{if(field==='gifts'){const av=(a.highlightUntil||0)>now?(a.highlightValue||a.lastGiftCoins||a.lastGiftCount||0):0,bv=(b.highlightUntil||0)>now?(b.highlightValue||b.lastGiftCoins||b.lastGiftCount||0):0;if(av!==bv)return bv-av;const coins=(b.totalGiftCoins||0)-(a.totalGiftCoins||0);if(coins)return coins}return b[field]-a[field]||(b.lastActivityAt||b.at||0)-(a.lastActivityAt||a.at||0)}).slice(0,count);const likes=sort(race.likers,'likes',race.settings.likerCount),gifts=sort(race.gifters,'gifts',race.settings.gifterCount);const groups=activeGift?[[gifts,'TOP GIFTERS','gifts'],[likes,'TOP LIKERS','likes']]:[[likes,'TOP LIKERS','likes'],[gifts,'TOP GIFTERS','gifts']];const freshness=groups.map(([rows])=>rows.map(p=>now-(p.lastActivityAt||p.at||0)<300000));const giftHighlights=gifts.map(p=>(p.highlightUntil||((p.lastGiftAt||p.at||0)+60000))>now);const key=JSON.stringify([groups,freshness,activeGift,giftHighlights]);root.hidden=false;if(root.dataset.key===key)return;root.dataset.key=key;root.replaceChildren(node('div','country-edge-prompt','Comment your country'));groups.forEach(([people,title,field],groupIndex)=>{const group=node('section','support-group');group.append(node('h3','',title));const list=node('div','support-list');people.forEach((person,i)=>{const fresh=field==='gifts'?(person.highlightUntil||((person.lastGiftAt||person.at||0)+60000))>now:freshness[groupIndex][i],featured=field==='gifts'?(person.highlightUntil||((person.lastGiftAt||person.at||0)+60000))>now:groupIndex===0&&i===0&&fresh;const card=node('div','spotlight-card'+(featured?' spotlight-featured':'')+(field==='gifts'&&i>0&&featured?' spotlight-minor':'')+(!fresh?' spotlight-idle':''));const face=avatar(person);face.querySelector('canvas').dataset.level=frameLevel(person,field);card.append(node('span','support-rank',String(i+1)),face,node('strong','',person.name),node('b','',(field==='likes'?'♥ ':'🎁 ')+(person[field]||0).toLocaleString('en-US')));if(field==='gifts'&&person.giftItems?.length){const gifts=node('div','donor-gifts');for(const item of person.giftItems){const token=node('span','donor-gift'),img=node('img');img.src=race.giftImages?.[item.id]||'/gifts/'+item.id+'.png';img.alt=item.name;img.onerror=()=>{img.replaceWith(node('span','','🎁'))};token.title=item.name;token.append(img,node('small','','×'+item.count));gifts.append(token)}card.append(gifts)}if(featured){const follow=followLink(person);if(follow)card.append(follow)}list.append(card)});if(!people.length)list.append(node('small','support-empty',field==='likes'?'LIKE':'GIFT'));group.append(list);root.append(group)})}

$('manualInputMethod').onchange=e=>send('race-settings',{settings:{playMode:e.target.value}});

$('modeMixed').onclick=()=>send('race-settings',{settings:{playMode:'mixed',entryMode:'auto',demoOpponents:true,giftsEnabled:true}});

function renderActivityTimers(){if(!race)return;const now=Date.now()+serverOffset;document.querySelectorAll('.lane').forEach((lane,i)=>{const p=race.slots[i],driver=lane.querySelector('.driver');let timer=driver.querySelector('.activity-timer');if(!timer){timer=node('span','activity-timer');timer.setAttribute('role','timer');driver.append(timer)}const until=p?.activeUntil||((p?.lastActivityAt||now)+(race.settings.joinGraceSeconds||30)*1000),remaining=Math.ceil((until-now)/1000);timer.hidden=!(p&&!p.isDemo&&race.settings.demoOpponents&&race.settings.entryMode!=='manual'&&race.settings.running&&!race.settings.paused&&race.winner===null&&remaining>0&&remaining<=(p?.hasRaceActivity?(race.settings.activeWarningSeconds||10):5));timer.textContent=String(Math.max(0,remaining));timer.setAttribute('aria-label',remaining+' seconds to like or gift');lane.classList.toggle('activity-warning',!timer.hidden)})}

function followLink(person){const handle=String(person?.uniqueId||'').replace(/^@/,'');if(!/^[A-Za-z0-9._]{1,32}$/.test(handle))return null;const link=node('a','spotlight-follow','Follow +');link.href='https://www.tiktok.com/@'+encodeURIComponent(handle);link.target='_blank';link.rel='noopener noreferrer';link.setAttribute('aria-label','Follow '+(person.name||handle)+' on TikTok');return link}

let lastInstructionKey='',lastInstructionAt=0,instructionStarting=false;function speakRaceInstructions(){if(!race||!window.RaceVoice)return;RaceVoice.configure(race.settings);if(window.RaceHost?.enabled||!screen||!race.settings.instructionVoice||!race.settings.sound||!race.settings.running||race.settings.paused||race.winner!==null||instructionStarting||RaceVoice.busy)return;const key=race.round+':'+race.settings.playMode+':'+race.settings.entryMode+':'+race.settings.voiceStyle;const now=Date.now();if(key===lastInstructionKey&&(!race.settings.instructionRepeat||now-lastInstructionAt<(race.settings.instructionRepeatSeconds||60)*1000))return;instructionStarting=true;RaceVoice.playClip(race.settings.entryMode==='manual'?'manual':race.settings.playMode).then(played=>{if(played){lastInstructionKey=key;lastInstructionAt=Date.now()}}).finally(()=>{instructionStarting=false})}

function renderCarMessages(){if(!race)return;const now=Date.now()+serverOffset;document.querySelectorAll('.lane').forEach((lane,i)=>{let label=lane.querySelector('.car-full-message');const m=race.carMessages?.[i],visible=m&&m.until>now;if(!label){label=node('span','car-full-message','FULL');label.setAttribute('role','status');lane.querySelector('.road').append(label)}label.hidden=!visible})}

$('refreshStudio').onclick=()=>{send('race-refresh-screen');$('refreshStudio').disabled=true;setTimeout(()=>{$('refreshStudio').disabled=false},2000)};

function showAudioStatus(m){const en=localStorage.getItem('race-panel-language')==='en';const labels=en?{ready:'Ready',playing:'Playing',blocked:'Autoplay blocked: click Enable sound in Studio',error:'Playback error',muted:'Muted',loading:'Loading voice'}:{ready:'آماده',playing:'در حال پخش',blocked:'پخش مسدود است؛ در منبع استودیو Enable sound را بزنید',error:'خطای پخش',muted:'صدا خاموش است',loading:'در حال بارگذاری صدا'};$('audioSourceStatus').textContent=(en?'Studio audio: ':'صدای استودیو: ')+(labels[m.status]||m.status)+' · '+(m.voice==='race'?(en?'Race audio':'صدای مسابقه'):m.voice==='persian'?'Dilara':m.voice==='bright'?'Jenny':'Aria')+(m.detail?' · '+m.detail:'')}window.addEventListener('race-audio-state',e=>{const m=e.detail;if(screen){$('audioUnlock').hidden=m.status!=='blocked';if(socket?.readyState===WebSocket.OPEN)socket.send(JSON.stringify({type:'race-audio-report',...m}))}else showAudioStatus(m)});$('audioUnlock').onclick=()=>{unlockEngineAudio();RaceVoice.unlock();$('audioUnlock').hidden=true;lastInstructionKey='';speakRaceInstructions()};

function updateRacePoints(){if(!race)return;const points=race.slots.slice(0,race.settings.cars).map(p=>Math.floor((p?.distance||0)/race.settings.step));document.querySelectorAll('.lane').forEach((lane,i)=>{const driver=lane.querySelector('.driver');let box=driver.querySelector('.driver-points');if(!box){box=node('div','driver-points');box.append(node('strong','point-total'),node('small','point-rival'),node('small','point-help'));const gift=driver.querySelector('.car-gift');driver.insertBefore(box,gift)}const total=points[i],rival=Math.max(0,...points.filter((_,n)=>n!==i)),p=race.slots[i];const value=box.querySelector('.point-total');if(value.dataset.points!==String(total)){value.dataset.points=total;value.textContent=total+' PTS';value.classList.remove('point-gain');void value.offsetWidth;value.classList.add('point-gain')}box.querySelector('.point-rival').textContent='VS '+rival;const events=(p?.assistHistory||[]).filter(x=>Date.now()+serverOffset-x.at<10000);const speed=events.length?events.reduce((sum,x)=>sum+x.points,0)/Math.max(1,Math.min(10,(Date.now()+serverOffset-events[0].at)/1000+1)):0;box.querySelector('.point-help').textContent=p&&!p.isDemo?'HELP '+(p.assistPoints||0)+' · '+speed.toFixed(1)+'/s':('AI '+(p?.aiLevel||race.settings.difficulty).toUpperCase());box.setAttribute('aria-label',total+' race points, strongest rival '+rival+' points')})}
let engineAudio=null,engineTestUntil=0;window.testRaceEngine=()=>{unlockEngineAudio();if(authorized){send('race-settings',{settings:{sound:true,engineSound:true,engineVolume:Math.max(25,Number($('settings').elements.namedItem('engineVolume')?.value)||25)}});send('race-audio-test',{kind:'engine'})}else{if(window.RaceSound)RaceSound.test('engine');else engineTestUntil=Date.now()+5000;updateEngineAudio()}};window.testRaceMusic=()=>{unlockEngineAudio();if(authorized){send('race-settings',{settings:{sound:true,musicEnabled:true,musicVolume:Math.max(45,Number($('settings').elements.namedItem('musicVolume')?.value)||55)}});send('race-audio-test',{kind:'music'})}else{RaceSound.test('music');updateEngineAudio()}};function unlockEngineAudio(){try{if(window.RaceSound)audio=RaceSound.unlock(audio);else{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume().catch(()=>{})}}catch{}}function stopEngineAudio(){if(!engineAudio)return;for(const osc of engineAudio.oscs){try{osc.stop();osc.disconnect()}catch{}}engineAudio.gain.disconnect();engineAudio.filter.disconnect();engineAudio=null}function updateEngineAudio(){if(window.RaceSound){RaceSound.update(race,screen,audio);return}const r=race;if((!screen&&Date.now()>=engineTestUntil)||!r)return;const running=Date.now()<engineTestUntil||r.settings.sound&&r.settings.engineSound&&r.settings.running&&!r.settings.paused&&r.winner===null&&Date.now()+serverOffset>=r.startsAt;if(!running){stopEngineAudio();return}if(!audio)unlockEngineAudio();if(audio?.state!=='running'){if(audio?.state==='suspended')audio.resume().catch(()=>{});$('audioUnlock').hidden=false;return;}if(!engineAudio){const gain=audio.createGain(),filter=audio.createBiquadFilter();filter.type='lowpass';filter.frequency.value=1400;filter.Q.value=.6;filter.connect(gain);gain.connect(audio.destination);const oscs=[audio.createOscillator(),audio.createOscillator()];oscs[0].type='triangle';oscs[1].type='sawtooth';oscs.forEach(o=>{o.connect(filter);o.start()});engineAudio={gain,filter,oscs}}const progress=Math.max(0,...r.slots.map(p=>(p?.distance||0)/r.settings.length));const pace=Math.max(0,...[...(window.Race3D?.motion?.rows?.values()||[])].map(row=>row.pace||0));const rpm=105+progress*125+Math.min(75,pace*18)+Math.sin(Date.now()/900)*6;engineAudio.oscs[0].frequency.setTargetAtTime(rpm,audio.currentTime,.35);engineAudio.oscs[1].frequency.setTargetAtTime(rpm*1.503,audio.currentTime,.35);const duck=(window.RaceVoice?.busy||window.RaceHost?.busy)? .35:1;const volume=(r.settings.volume/100)*(r.settings.engineVolume??18)/100*.7*duck;engineAudio.gain.gain.setTargetAtTime(volume,audio.currentTime,.2)}

for(const event of ['input','change'])document.getElementById('panel').addEventListener(event,e=>{if(e.target.form===$('settings'))$('settings').dataset.dirty='true'});

function drawCloudProfileRing(ctx,cx,cy,_radius,level,time,options={}){const colors={cloud:'#bee7ff',simple:'#b5ddf5',glow:'#71f5d5',silver:'#e6efff',gold:'#ffdf89',ice:'#88edff',fire:'#ffb6a2'},color=colors[level]||colors.cloud;const t=time/1000*(options.speed||1),cloudCount={cloud:16,simple:14,glow:18,silver:20,gold:22,ice:24,fire:26}[level]||16;ctx.save();ctx.strokeStyle=color;ctx.globalAlpha=.38;ctx.lineWidth=2;ctx.beginPath();ctx.arc(cx,cy,57,0,Math.PI*2);ctx.stroke();for(let i=0;i<cloudCount;i++){const a=i*Math.PI*2/cloudCount+t*.3,r=57+Math.sin(i*2.4+t)*3,x=cx+Math.cos(a)*r,y=cy+Math.sin(a)*r,size=5+(Math.sin(i*1.9+t)*.5+.5)*7;const mist=ctx.createRadialGradient(x,y,0,x,y,size);mist.addColorStop(0,color+'a0');mist.addColorStop(1,color+'00');ctx.globalAlpha=.58;ctx.fillStyle=mist;ctx.beginPath();ctx.arc(x,y,size,0,Math.PI*2);ctx.fill()}for(let i=0;i<12;i++){const a=i*2.399+t*(.25+i*.018),r=62+Math.sin(i*2+t)*7;ctx.globalAlpha=.35+(Math.sin(t*1.4+i)+1)*.25;ctx.fillStyle=color;ctx.beginPath();ctx.arc(cx+Math.cos(a)*r,cy+Math.sin(a)*r,1.2+(i%3)*.5,0,Math.PI*2);ctx.fill()}ctx.restore()}

function updateMovePrompt(now=Date.now()+serverOffset){if(!race)return;const prompt=$('movePrompt'),elapsed=(now-race.startsAt)/1000,active=race.settings.running&&!race.settings.paused&&race.winner===null;const spotlight=active&&elapsed>=0&&(elapsed<3||(elapsed>=20&&elapsed%20<1.6));prompt.hidden=race.winner!==null;prompt.classList.toggle('prompt-docked',!spotlight);prompt.classList.toggle('prompt-intro',spotlight)}

setInterval(()=>{if(socket?.readyState===WebSocket.OPEN){if(Date.now()-lastSocketMessageAt>25000){socket.close();return}socket.send(JSON.stringify({type:'race-heartbeat'}))}},8000);
window.addEventListener('online',()=>{if(!socket||socket.readyState>1)connect()});
